import{_ as c,r as e,o as l,c as i,e as t,a as n,s as r,d as s}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Building Console Commands - October CMS - 3.x","titleTemplate":false,"description":"Create your own commands that run in the console.","frontmatter":{"subtitle":"Create your own commands that run in the console."},"headers":[{"level":2,"title":"Building a Command","slug":"building-a-command","link":"#building-a-command","children":[{"level":3,"title":"Defining Arguments","slug":"defining-arguments","link":"#defining-arguments","children":[]},{"level":3,"title":"Defining Options","slug":"defining-options","link":"#defining-options","children":[]},{"level":3,"title":"Retrieving Input","slug":"retrieving-input","link":"#retrieving-input","children":[]},{"level":3,"title":"Writing Output","slug":"writing-output","link":"#writing-output","children":[]}]},{"level":2,"title":"Registering Commands","slug":"registering-commands","link":"#registering-commands","children":[{"level":4,"title":"Registering a Console Command","slug":"registering-a-console-command","link":"#registering-a-console-command","children":[]},{"level":4,"title":"Registering a Command in the Application Container","slug":"registering-a-command-in-the-application-container","link":"#registering-a-command-in-the-application-container","children":[]}]},{"level":2,"title":"Calling Other Commands","slug":"calling-other-commands","link":"#calling-other-commands","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/extend/console-commands.md","filePath":"3.x/extend/console-commands.md"}'),u={name:"3.x/extend/console-commands.md"};function d(g,a,k,m,h,v){const o=e("pre-heading"),p=e("post-heading");return l(),i("div",null,[t(o),a[0]||(a[0]=n("h1",null,"Building Console Commands",-1)),t(p),a[1]||(a[1]=r(`<p>To build your own custom commands for working with your application, store them within the plugin <strong>console</strong> directory. You may generate the class file using the command line scaffolding tool. The first argument specifies the author and plugin name. The second argument specifies the command name.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:command Acme.Blog MyCommand
</code></pre></div><h2 id="building-a-command"><a href="#building-a-command" class="header-anchor">#</a> Building a Command</h2><p>If you wanted to create a console command called <code>acme:mycommand</code>, you might create the associated class for that command in a file called <strong>plugins/acme/blog/console/MyCommand.php</strong> and paste the following contents to get started:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Console</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Illuminate<span class="token punctuation">\\</span>Console<span class="token punctuation">\\</span>Command</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Symfony<span class="token punctuation">\\</span>Component<span class="token punctuation">\\</span>Console<span class="token punctuation">\\</span>Input<span class="token punctuation">\\</span>InputOption</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Symfony<span class="token punctuation">\\</span>Component<span class="token punctuation">\\</span>Console<span class="token punctuation">\\</span>Input<span class="token punctuation">\\</span>InputArgument</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">MyCommand</span> <span class="token keyword">extends</span> <span class="token class-name">Command</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var string signature for the console command.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme:mycommand {user}&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * @var string description for the console command.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$description</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Does something cool.&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * handle executes the console command.
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">handle</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$username</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">argument</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">output</span><span class="token operator">-&gt;</span><span class="token function">writeln</span><span class="token punctuation">(</span><span class="token string double-quoted-string">&quot;Hello <span class="token interpolation"><span class="token punctuation">{</span><span class="token variable">$username</span><span class="token punctuation">}</span></span>!&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Once your class is created you should fill out the <code>signature</code> and <code>description</code> properties of the class, which will be used when displaying your command on the command <code>list</code> screen.</p><p>The <code>handle</code> method will be called when your command is executed. You may place any command logic in this method.</p><h3 id="defining-arguments"><a href="#defining-arguments" class="header-anchor">#</a> Defining Arguments</h3><p>All user supplied arguments and options are wrapped in curly braces in the signature. In the following example, the command defines one required argument: user:</p><p>Arguments are defined in the signature as wrapped curly braces, where you may define any arguments your command receives. For example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also make arguments optional by placing a question mark (<code>?</code>) after the argument name.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user?}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Alternatively, supply a default value with an equal sign (<code>=</code>) followed by the default value.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user=foo}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="defining-options"><a href="#defining-options" class="header-anchor">#</a> Defining Options</h3><p>Options, like arguments, are another form of user input and are defined by two hyphens (<code>--</code>) in the signature. Options can can optionally receive a value, without a value, they serve as a boolean switch value. For example, a switch value named <strong>queue</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user} {--queue}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>In this example, the <code>--queue</code> switch may be specified when calling the command. If the <code>--queue</code> switch is passed, the value of the option will be <code>true</code>. Otherwise, the value will be <code>false</code>.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan mail:send <span class="token number">1</span> <span class="token parameter variable">--queue</span>
</code></pre></div><p>When an option expects a value, you should suffix the input name with an equal sign (<code>=</code>).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user} {--queue=}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>In this case, the option can accept a value, otherwise the value will be <code>null</code>.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan mail:send <span class="token number">1</span> <span class="token parameter variable">--queue</span><span class="token operator">=</span>default
</code></pre></div><p>You may also specify a default value with an equal sign (<code>=</code>) followed by the default value.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user} {--queue=default}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Shortcuts are a shorter syntax when triggering an option.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$signature</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mail:send {user} {--Q|queue}&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>There is an important difference when calling a shortcut. It should be prefixed with a single hyphen (<code>-</code>) and no equal sign is used to supply a value.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan mail:send <span class="token number">1</span> <span class="token parameter variable">-Qdefault</span>
</code></pre></div><h3 id="retrieving-input"><a href="#retrieving-input" class="header-anchor">#</a> Retrieving Input</h3><p>While your command is executing, you will obviously need to access the values for the arguments and options accepted by your application. To do so, you may use the <code>argument</code> and <code>option</code> methods.</p><p>Supply a name to the <code>argument</code> method to retrieve the value of a command argument.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">argument</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Without a name, it will retrieve all arguments.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$arguments</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">argument</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Passing a name to the <code>option</code> method will retrieve the value of a command option.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">option</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Without a name, it will retrieve all options.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$options</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">option</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="writing-output"><a href="#writing-output" class="header-anchor">#</a> Writing Output</h3><p>To send output to the console, you may use the <code>info</code>, <code>comment</code>, <code>question</code> and <code>error</code> methods. Each of these methods will use the appropriate ANSI colors for their purpose.</p><p>The <code>info</code> method sends information back to the user.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Display this on the screen&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>error</code> method is used for sending an error message.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Something went wrong!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also use the <code>ask</code> and <code>confirm</code> methods to prompt the user for input.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$name</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">ask</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;What is your name?&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>secret</code> method is used for asking the user for secret input.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$password</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">secret</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;What is the password?&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>confirm</code> method asks the user for confirmation and returns <code>true</code> if the user accepts.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">confirm</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Do you wish to continue? [yes|no]&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may also specify a default value to the <code>confirm</code> method, which should be <code>true</code> or <code>false</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">confirm</span><span class="token punctuation">(</span><span class="token variable">$question</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="registering-commands"><a href="#registering-commands" class="header-anchor">#</a> Registering Commands</h2><h4 id="registering-a-console-command"><a href="#registering-a-console-command" class="header-anchor">#</a> Registering a Console Command</h4><p>Once your command class is finished, you need to register it so it will be available for use. This is typically done in the <code>register</code> method of a <a href="./extending.html">plugin registration file</a> using the <code>registerConsoleCommand</code> helper method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Blog</span> <span class="token keyword">extends</span> <span class="token class-name">PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">pluginDetails</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">register</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">registerConsoleCommand</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.mycommand&#39;</span><span class="token punctuation">,</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Console<span class="token punctuation">\\</span>MyConsoleCommand</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Alternatively, plugins can supply a file named <strong>init.php</strong> in the plugin directory that you can use to place command registration logic. Within this file, you may use the <code>Artisan::add</code> method to register the command.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Artisan</span><span class="token operator">::</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Console<span class="token punctuation">\\</span>MyCommand</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="registering-a-command-in-the-application-container"><a href="#registering-a-command-in-the-application-container" class="header-anchor">#</a> Registering a Command in the Application Container</h4><p>If your command is registered in the <a href="./services/application.html">application container</a>, you may use the <code>Artisan::resolve</code> method to make it available to Artisan.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Artisan</span><span class="token operator">::</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;binding.name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="calling-other-commands"><a href="#calling-other-commands" class="header-anchor">#</a> Calling Other Commands</h2><p>Sometimes you may wish to call other commands from your command. You may do so using the <code>call</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;october:migrate&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can also pass arguments as an array.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;plugin:refresh&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;October.Demo&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>As well as options.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;october:update&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;--force&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4>`,71)),a[2]||(a[2]=n("div",{class:"custom-block also"},[n("ul",null,[n("li",null,[n("a",{href:"https://laravel.com/docs/10.x/artisan",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("Laravel Artisan Console Documentation"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),n("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const w=c(u,[["render",d]]);export{y as __pageData,w as default};
